-- 0107 first carried the Sample Institute's logo as WebP, which receipts, certificates and e-mails cannot print; it
-- was changed to the PNG. A database that ran the WebP one gets the PNG here (a logo uploaded since is left alone).
UPDATE organisations SET branding = jsonb_set(branding, '{logo}', to_jsonb('data:image/png;base64,'::text))
WHERE id = '00000000-0000-4000-8000-000000000001' AND branding->>'logo' LIKE 'data:image/webp;%';
